@push('scripts')<script>const dateInput=document.querySelector('#tanggal_sesi'),slots=document.querySelector('#slots'),selected=document.querySelector('#jam_mulai');dateInput?.addEventListener('change',async()=>{slots.innerHTML='<p class="col-span-full p-8 text-center text-slate-500">Memuat slot...</p>';const draft=@json($draft);const response=await fetch(`{{ route('booking.slots') }}?id_room=${draft.id_room}&id_package=${draft.id_package}&tanggal_sesi=${dateInput.value}`);const result=await response.json();slots.innerHTML='';if(!result.success||!result.data?.length){slots.innerHTML='<p class="col-span-full rounded-2xl bg-amber-50 p-8 text-center text-amber-700">Tidak ada slot kosong pada tanggal ini.</p>';return;}result.data.forEach(slot=>{const time=typeof slot==='string'?slot:(slot.jam_mulai??slot.time);const button=document.createElement('button');button.type='button';button.textContent=time;button.className='slot-button';button.onclick=()=>{selected.value=time;document.querySelectorAll('.slot-button').forEach(item=>item.classList.remove('selected'));button.classList.add('selected')};slots.appendChild(button)});});</script>@endpush